// Command escpos-demo prints a capability test receipt on an Epson TM-T20IV
// (or a compatible ESC/POS thermal printer) over raw TCP port 9100.
//
// It demonstrates fonts, text effects, CP858 special characters and the bar
// code / 2D code commands that were verified against a real TM-T20IV:
//
//	1D (GS k, function B): CODE39, EAN-13, CODE93, CODE128, GS1 DataBar
//	2D (GS ( k, with family-specific cn): QR, PDF417, DataMatrix, Aztec
//
// Usage:
//
//	escpos-demo [ADDR]     // ADDR defaults to 192.168.1.185:9100
//
// The generated bytes are written to the printer socket directly. To capture
// them to a file instead, redirect e.g. with a small netcat-style helper.
package main

import (
	"fmt"
	"net"
	"os"
	"time"
)

// cp858 maps the German special characters used below to their CP858 bytes,
// so the printer's code page (set via ESC t 19) renders them correctly.
var cp858 = map[rune]byte{'ä': 0x84, 'ö': 0x94, 'ü': 0x81, 'Ä': 0x8E, 'Ö': 0x99, 'Ü': 0x9A, 'ß': 0xE1, '€': 0xD5}

// enc maps a UTF-8 string to CP858 bytes; unmapped non-ASCII runes become '?'.
func enc(s string) []byte {
	out := make([]byte, 0, len(s))
	for _, r := range s {
		if b, ok := cp858[r]; ok {
			out = append(out, b)
		} else if r < 0x80 {
			out = append(out, byte(r))
		} else {
			out = append(out, '?')
		}
	}
	return out
}

func line(s string) []byte { return append(enc(s), '\n') }

var (
	initCmd  = []byte{0x1b, 0x40} // ESC @
	cp858Cmd = []byte{0x1b, 0x74, 19}
	lsCmd    = []byte{0x1b, '2'} // default line spacing
	fontA    = []byte{0x1b, 0x4d, 0x00}
	fontB    = []byte{0x1b, 0x4d, 0x01}
	alignL   = []byte{0x1b, 0x61, 0x00}
	alignC   = []byte{0x1b, 0x61, 0x01}
	empOn    = []byte{0x1b, 0x45, 0x01}
	empOff   = []byte{0x1b, 0x45, 0x00}
	dsOn     = []byte{0x1b, 0x47, 0x01}
	dsOff    = []byte{0x1b, 0x47, 0x00}
	ulOn     = []byte{0x1b, '-', 0x01}
	ulOff    = []byte{0x1b, '-', 0x00}
	sizeNorm = []byte{0x1d, 0x21, 0x00}
	size2x   = []byte{0x1d, 0x21, 0x11}
)

func feed(n int) []byte { return append([]byte{'\n'}, 0x1b, 'd', byte(n)) }

// gskB builds a 1D bar code in GS k function B form: GS k m n d1..dn.
// For the TM-T20IV the valid-ASCII m range is 65-79 and n is a length byte.
func gskB(m byte, data string) []byte {
	b := []byte{0x1d, 0x6b, m, byte(len(data))}
	return append(b, []byte(data)...)
}

// store builds the "GS ( k pL pH cn P m <data>" store-in-storage command.
// cn selects the 2D code family (48=PDF417, 49=QR, 53=Aztec, 54=DataMatrix).
func store(cn byte, data string) []byte {
	b := []byte{0x1d, 0x28, 0x6b, byte(3 + len(data)), 0x00, cn, 0x50, 0x30}
	return append(b, []byte(data)...)
}

// prn builds the "GS ( k 03 00 cn Q m" print-symbol command.
func prn(cn byte) []byte { return []byte{0x1d, 0x28, 0x6b, 0x03, 0x00, cn, 0x51, 0x30} }

// qr renders a QR code of data using the GS ( k sequence for cn=49.
func qr(data string, mod byte) []byte {
	out := []byte{0x1d, 0x28, 0x6b, 0x04, 0x00, 0x31, 0x41, 0x32, 0x00} // model 2
	out = append(out, 0x1d, 0x28, 0x6b, 0x03, 0x00, 0x31, 0x43, mod)    // module size
	out = append(out, 0x1d, 0x28, 0x6b, 0x03, 0x00, 0x31, 0x45, 0x48)   // err corr low
	out = append(out, store(0x31, data)...)
	out = append(out, prn(0x31)...)
	return out
}

func main() {
	addr := "192.168.1.185:9100" // printer default; override with first argument
	if len(os.Args) > 1 {
		addr = os.Args[1]
	}

	conn, err := net.DialTimeout("tcp", addr, 10*time.Second)
	if err != nil {
		fmt.Fprintln(os.Stderr, "escpos-demo:", err)
		os.Exit(1)
	}
	defer conn.Close()

	var d []byte
	d = append(d, initCmd...)
	d = append(d, cp858Cmd...)
	d = append(d, lsCmd...)

	// Header
	d = append(d, alignC...)
	d = append(d, empOn...)
	d = append(d, line("logprint - full ESC/POS demo")...)
	d = append(d, empOff...)
	d = append(d, line("TM-T20IV")...)
	d = append(d, feed(1)...)

	// Fonts
	d = append(d, alignL...)
	d = append(d, fontA...)
	d = append(d, line("Font A (48 cols)")...)
	d = append(d, line("123456789012345678901234567890123456789012345678")...)
	d = append(d, fontB...)
	d = append(d, line("Font B (64 cols)")...)
	d = append(d, line("1234567890 1234567890 1234567890 1234567890 1234567890 12345678")...)
	d = append(d, fontA...)
	d = append(d, feed(1)...)

	// Effects
	d = append(d, empOn...)
	d = append(d, line("Bold")...)
	d = append(d, empOff...)
	d = append(d, dsOn...)
	d = append(d, line("Double-strike")...)
	d = append(d, dsOff...)
	d = append(d, ulOn...)
	d = append(d, line("Underlined")...)
	d = append(d, ulOff...)
	d = append(d, size2x...)
	d = append(d, alignC...)
	d = append(d, line("DOUBLE")...)
	d = append(d, sizeNorm...)
	d = append(d, alignL...)
	d = append(d, feed(1)...)

	// Special characters (CP858)
	d = append(d, line("CP858: a"+string([]rune{'ä', 'ö', 'ü'})+" A"+string([]rune{'Ä', 'Ö', 'Ü'})+" ss="+string([]rune{'ß'})+" Euro="+string([]rune{'€'}))...)
	d = append(d, feed(1)...)

	// ---- 1D bar codes (GS k function B) ----
	d = append(d, alignC...)
	d = append(d, 0x1d, 0x68, 50, 0x1d, 0x48, 2, 0x1d, 0x66, 1) // height 50, HRI below, font B
	d = append(d, line("CODE39")...)
	d = append(d, gskB(69, "LOGP-2026")...)
	d = append(d, feed(1)...)
	d = append(d, line("EAN-13")...)
	d = append(d, gskB(67, "4006381333931")...)
	d = append(d, feed(1)...)
	d = append(d, line("CODE93")...)
	d = append(d, gskB(72, "LOGP-2026-05-12")...)
	d = append(d, feed(1)...)
	d = append(d, line("CODE128 (set B)")...)
	d = append(d, gskB(73, "{B"+"LOGPRINT")...)
	d = append(d, feed(1)...)
	d = append(d, line("GS1 DataBar Omni")...)
	d = append(d, gskB(75, "2001234567890")...)
	d = append(d, feed(1)...)
	d = append(d, line("GS1 DataBar Limited")...)
	d = append(d, gskB(77, "1501234567890")...)
	d = append(d, feed(2)...)

	// ---- 2D codes (GS ( k, family-specific cn) ----
	d = append(d, line("QR Code")...)
	d = append(d, qr("https://example.com/demo", 6)...)
	d = append(d, feed(1)...)
	d = append(d, line("PDF417")...)
	d = append(d, 0x1d, 0x28, 0x6b, 0x03, 0x00, 0x30, 0x41, 0x00) // columns auto
	d = append(d, 0x1d, 0x28, 0x6b, 0x03, 0x00, 0x30, 0x43, 0x04) // module 4
	d = append(d, store(0x30, "PDF417-2026-LOGP")...)
	d = append(d, prn(0x30)...)
	d = append(d, feed(1)...)
	d = append(d, line("DataMatrix")...)
	d = append(d, 0x1d, 0x28, 0x6b, 0x03, 0x00, 0x36, 0x43, 0x03) // module 3
	d = append(d, store(0x36, "LOGP-DM-2026")...)
	d = append(d, prn(0x36)...)
	d = append(d, feed(1)...)
	d = append(d, line("Aztec")...)
	d = append(d, store(0x35, "AZTEC-LOGP")...)
	d = append(d, prn(0x35)...)
	d = append(d, feed(1)...)

	d = append(d, feed(2)...)
	d = append(d, 0x1d, 0x56, 66, 0) // feed + cut

	if _, err := conn.Write(d); err != nil {
		fmt.Fprintln(os.Stderr, "escpos-demo:", err)
		os.Exit(1)
	}
	fmt.Printf("sent %d bytes to %s\n", len(d), addr)
}
